// Campaigns still running after 24 hours, oldest first, locked for the sweep.
func (q *Queries) StaleCampaigns(ctx context.Context, orgID ids.OrgID, maxRows int32) ([]PcCampaign, error) {
	rows, err := q.db.Query(ctx, staleCampaigns, orgID, maxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PcCampaign{}
	for rows.Next() {
		var i PcCampaign
		if err := rows.Scan(
			&i.OrgID,
			&i.ID,
			&i.RangeAgentID,
			&i.StartedBy,
			&i.RunnerVersion,
			&i.SetDigest,
			&i.ScenarioIds,
			&i.ImageDigest,
			&i.ModelHost,
			&i.RelayConnectionID,
			&i.Scripted,
			&i.State,
			&i.StartedAt,
			&i.FinishedAt,
			&i.OpenStep,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const transitionCampaign = `-- name: TransitionCampaign :one
UPDATE pc.campaigns SET state = $1
WHERE org_id = $2 AND id = $3 AND state = 'RUNNING'
RETURNING finished_at
`

// A conditional state change: nothing happens unless the campaign still runs.
func (q *Queries) TransitionCampaign(ctx context.Context, state string, orgID ids.OrgID, iD ids.UUID) (*time.Time, error) {
	row := q.db.QueryRow(ctx, transitionCampaign, state, orgID, iD)
	var finished_at *time.Time
	err := row.Scan(&finished_at)
	return finished_at, err
}
